mapper.update:
update student_point_account
set streak_days = #{streakDays}, last_streak_date = #{lastStreakDate}, update_time = now()
where user_id = #{userId}

mapper.select:
select t.user_id as userId, t.points as points, a.stage as stage, a.level as level, u.nick_name as nickName from (
select r.user_id as user_id, coalesce(sum(r.points), 0) as points from student_point_record r where r.create_time >= #{startTime} and r.points > 0 group by r.user_id
select p.user_id as user_id, p.total_points as points from student_point_account p
) t join student_point_account a on a.user_id = t.user_id left join user_info u on u.user_id = t.user_id where t.points > 0 and a.stage = #{stage} order by t.points desc, a.update_time asc limit #{limit}

select count(1) from student_point_account a
where a.total_points > #{points}
and a.stage = #{stage}
